input.command:
cd AlgebraicJacobian && for f in Albanese/*.lean RigidityLemma.lean; do
python3 - "$f" <<'EOF'
import sys,re
p=sys.argv[1]
src=open(p).read()
# strip block comments and line comments
out=[];i=0;n=len(src);depth=0
lines=src.split('\n')
res=[]
depth=0
for ln,line in enumerate(lines,1):
    j=0;kept=''
    while j<len(line):
        if depth==0 and line.startswith('/-',j):
            depth+=1;j+=2
        elif depth>0 and line.startswith('-/',j):
            depth-=1;j+=2
        elif depth>0:
            j+=1
        elif line.startswith('--',j):
            break
        else:
            kept+=line[j];j+=1
    if depth==0 or True:
        if re.search(r'(?<![A-Za-z_.])sorry(?![A-Za-z_])',kept):
            res.append((ln,kept.strip()[:100]))
if res:
    print(f"=== {p}: {len(res)}")
    for ln,t in res: print(f"  {ln}: {t}")
EOF
done
